    {
      "name": "Trust Logo Strip",
      "role": "Social proof line below the hero CTAs",
      "description": "Horizontal row of partner/user logos at 32–40px height, rendered in monochrome gray (#838383 or #c2c2c2). Preceded by a small caption: 'Trusted by 30,000+ teams, builders and creators'. Logos are evenly spaced with 24–32px gaps, left-aligned to the text column."
    },
    {
      "name": "Footer Link Column",
      "role": "Site-map navigation in the footer",
      "description": "Vertical stack of 14–15px text links in #838383 (Graphite), 8px row gap. Column heading is 15–16px weight 500 in #202020. Six columns typically: Product, Additional Links, Cap, Use Cases, Socials, Tools."
    },
    {
      "name": "Chat Widget",
      "role": "Persistent floating support button",
      "description": "Fixed-position, bottom-right. 48px circle, #202020 background, white speech-bubble icon. Sits above all other content with a subtle 0px 10px 15px rgba(0,0,0,0.1) shadow."
    }
